"""LP-68: branches. Every existing restaurant gets branch 1 from its current
address and area, and every existing offer is attached to its restaurant's
branch 1, so restaurants and offers made before branches keep working."""

import django.db.models.deletion
from django.db import migrations, models


def give_every_shop_its_first_branch(apps, schema_editor):
    Shop = apps.get_model("marketplace", "Shop")
    Branch = apps.get_model("marketplace", "Branch")
    Listing = apps.get_model("marketplace", "Listing")

    for shop in Shop.objects.order_by("id").iterator():
        if Branch.objects.filter(shop_id=shop.id).exists():
            continue
        branch = Branch.objects.create(
            shop_id=shop.id,
            name=(shop.area or "").strip()[:100] or "Main branch",
            address=shop.address or "",
            area=shop.area or "",
            position=1,
        )
        Listing.objects.filter(shop_id=shop.id, branch__isnull=True).update(branch=branch)


def forget_branches(apps, schema_editor):
    # Going back: offers lose their branch first, so branches can be dropped.
    apps.get_model("marketplace", "Listing").objects.update(branch=None)


